+// Delay computes the retry delay for the given one-based attempt number.
+// attempt 1 returns base; each subsequent attempt doubles the previous
+// value, saturating at maximum without overflowing.
 func Delay(attempt int, base, maximum time.Duration) (time.Duration, error) {
-	return 0, nil
+	if attempt < 1 {
+		return 0, fmt.Errorf("retrydelay: attempt must be >= 1, got %d", attempt)
+	}
+	if base <= 0 {
+		return 0, errors.New("retrydelay: base must be > 0")
+	}
+	if maximum <= 0 {
+		return 0, errors.New("retrydelay: maximum must be > 0")
+	}
+	if base > maximum {
+		return 0, errors.New("retrydelay: base must be <= maximum")
+	}
+
+	delay := base
+	for i := 1; i < attempt; i++ {
+		if delay > maximum/2 {
+			return maximum, nil
+		}
+		delay *= 2
+		if delay > maximum {
+			return maximum, nil
+		}
+	}
+	return delay, nil
 }
